'use strict';
const ARCADE_GAMES={
 flappy:{title:'Flappy Lemon',price:50000,help:'Tap or press Space / ↑ to flap. Dodge the lemon squeezers for 10K clicks each. Avoid the edges!'},
 cookies:{title:'Cosmic Cookie Catch',price:100000,help:'Drag your tray or use ← / →. Catch cookies for at least 2K clicks each. Avoid glowing meteors. A run lasts 30 seconds.'},
 pop:{title:'Lemon Pop',price:150000,help:'Tap ripe golden lemons before they float away. Purple sour lemons cost a heart! Earn 3K clicks per ripe lemon, with streak bonuses up to ×5. You have 30 seconds and three hearts.'},
 rush:{title:'Lemonade Rush',price:250000,help:'Match the customer’s order by tapping a drink below, or press 1, 2 or 3. Serve quickly for 5K clicks per order and streak bonuses up to ×8. Three wrong drinks end your 30-second shift.'}
};
const ARCADE_PRICES=Object.fromEntries(Object.entries(ARCADE_GAMES).map(([key,game])=>[key,game.price]));
const canvas=$('arcade'),ctx=canvas.getContext('2d');
const arcadeWorlds=new Image(),arcadeSprites=new Image();
arcadeWorlds.src='images/arcade-worlds.png';arcadeSprites.src='images/arcade-sprites.png';
for(const image of [arcadeWorlds,arcadeSprites])image.onload=()=>{if($('arcade-dialog').open&&!running)drawArcade();};
let mode='flappy',running=false,raf=0,prevTime=0,runScore=0,runEarned=0,elapsed=0,spawn=0,obstacles=[],falling=[],lemonY=210,velocity=0,basketX=300,leftHeld=false,rightHeld=false,hearts=3,streak=0,order=0,orderTime=0,feedback='',feedbackUntil=0;
function stopArcade(){running=false;cancelAnimationFrame(raf);raf=0;leftHeld=rightHeld=false;}
function unlockArcade(next){if(window.cloudPaused||!Object.hasOwn(ARCADE_GAMES,next))return false;if(!arcadeUnlocks[next]){repairNumbers();const price=ARCADE_PRICES[next];if(clicks<price){notify(`You need ${fmt(price)} bank clicks to unlock this game.`);return false;}clicks=finiteAmount(clicks-price);arcadeUnlocks[next]=true;purchases++;update();saveGame();notify(`${ARCADE_GAMES[next].title} unlocked! It stays unlocked through rebirths.`);}openArcade(next);return true;}
function openArcade(next){if(window.cloudPaused||!arcadeUnlocks[next]||!Object.hasOwn(ARCADE_GAMES,next))return;stopArcade();mode=next;obstacles=[];falling=[];lemonY=210;basketX=300;elapsed=runScore=runEarned=0;$('arcade-title').textContent=ARCADE_GAMES[mode].title;$('arcade-help').textContent=ARCADE_GAMES[mode].help;$('arcade-score').textContent='Ready? Rewards go straight to your bank.';$('arcade-start').textContent='Start game';$('arcade-dialog').showModal();drawArcade();}
for(const key of Object.keys(ARCADE_GAMES))$('open-'+key).addEventListener('click',()=>unlockArcade(key));
$('arcade-close').addEventListener('click',()=>$('arcade-dialog').close());$('arcade-dialog').addEventListener('close',stopArcade);$('arcade-dialog').addEventListener('cancel',stopArcade);
function startArcade(){if(window.cloudPaused||!arcadeUnlocks[mode])return;stopArcade();runScore=runEarned=elapsed=spawn=streak=0;hearts=3;obstacles=[];falling=[];lemonY=210;velocity=-180;basketX=300;order=Math.floor(Math.random()*3);orderTime=0;feedback='';running=true;prevTime=performance.now();$('arcade-start').textContent='Restart run';canvas.focus();raf=requestAnimationFrame(frame);}
$('arcade-start').addEventListener('click',startArcade);
function endArcade(message){stopArcade();arcadeBest=Math.max(arcadeBest,mode==='flappy'?runScore:0);update();saveGame();const unit={flappy:'dodged',cookies:'cookies',pop:'lemons',rush:'orders'}[mode];$('arcade-score').textContent=`${message} ${runScore} ${unit} · +${fmt(runEarned)} clicks`;$('arcade-start').textContent='Play again';drawArcade();}
function earnArcade(amount){runEarned=addAmount(runEarned,reward(amount));}
function scoreDodge(){arcadeDodges++;runScore++;earnArcade(10000);}
function mistake(message){hearts--;streak=0;feedback=message;feedbackUntil=elapsed+1;if(hearts<=0)endArcade('Time for a fresh squeeze!');}
function serveDrink(choice){if(!running||window.cloudPaused||mode!=='rush')return;if(choice!==order){mistake('Oops! Try the drink on the order card.');return;}ordersServed++;runScore++;streak++;earnArcade(5000*Math.min(8,1+Math.floor(streak/3)));feedback='Perfect pour!';feedbackUntil=elapsed+.55;order=(order+1+Math.floor(Math.random()*2))%3;orderTime=elapsed;}
function stepArcade(dt){elapsed+=dt;spawn+=dt;if(mode==='flappy'){velocity+=660*dt;lemonY+=velocity*dt;if(spawn>1.8){spawn=0;obstacles.push({x:620,gap:105+Math.random()*210,passed:false});}const speed=155+Math.min(80,runScore*3);for(const o of obstacles){o.x-=speed*dt;if(o.x+52<138&&!o.passed){o.passed=true;scoreDodge();}if(o.x<182&&o.x+52>138&&(lemonY-20<o.gap-80||lemonY+20>o.gap+80)){endArcade('Squeezed!');return;}}obstacles=obstacles.filter(o=>o.x>-60);if(lemonY<20||lemonY>400){endArcade('Squeezed!');return;}}
 else if(mode==='cookies'){basketX=Math.max(48,Math.min(552,basketX+((rightHeld?1:0)-(leftHeld?1:0))*360*dt));if(spawn>.45){spawn=0;falling.push({x:25+Math.random()*550,y:-25,meteor:Math.random()<.23});}for(const f of falling){f.y+=180*dt;if(!f.done&&f.y>=350&&f.y<=390&&Math.abs(f.x-basketX)<48){f.done=true;if(f.meteor){endArcade('Meteor bonk!');return;}cookiesCaught++;runScore++;earnArcade(Math.max(2000,multiplyAmount(multiplyAmount(baseRate,autoMult),2)));}}falling=falling.filter(f=>f.y<450&&!f.done);}
 else if(mode==='pop'){if(spawn>.65){spawn=0;falling.push({x:45+Math.random()*510,y:345,age:0,sour:Math.random()<.2,seed:Math.random()*6});}for(const f of falling){f.age+=dt;f.y-=38*dt;}falling=falling.filter(f=>!f.done&&f.age<3.4);}
 else if(mode==='rush'&&elapsed-orderTime>Math.max(2.6,5-runScore*.07)){mistake('Order timed out. Next customer!');order=(order+1)%3;orderTime=elapsed;}
 if(mode!=='flappy'&&elapsed>=30&&running){endArcade('Lovely shift!');return;}const unit={flappy:'dodged',cookies:'caught',pop:'popped',rush:'served'}[mode];$('arcade-score').textContent=`${runScore} ${unit} · +${fmt(runEarned)} clicks${mode!=='flappy'?' · '+Math.max(0,Math.ceil(30-elapsed))+'s':''}`;
}
// Generated artwork is an atlas: four illustrated scenes and eight transparent sprites.
const SPRITE_BOUNDS=[[0,0,453,440],[502,0,339,462],[907,70,399,395],[1331,0,443,466],[0,621,538,207],[537,458,332,429],[960,459,341,428],[1365,448,381,439]];
function sprite(index,x,y,w,h,angle=0){if(!arcadeSprites.complete||!arcadeSprites.naturalWidth)return;const [sx,sy,sw,sh]=SPRITE_BOUNDS[index];if(index!==1){const scale=Math.min(w/sw,h/sh);w=sw*scale;h=sh*scale;}ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.drawImage(arcadeSprites,sx,sy,sw,sh,-w/2,-h/2,w,h);ctx.restore();}
function pill(x,y,w,h,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,14);ctx.fill();}
function drawArcade(){const panel=Object.keys(ARCADE_GAMES).indexOf(mode);ctx.clearRect(0,0,600,420);if(arcadeWorlds.complete&&arcadeWorlds.naturalWidth){const sw=arcadeWorlds.naturalWidth/2,sh=arcadeWorlds.naturalHeight/2;ctx.drawImage(arcadeWorlds,panel%2*sw,Math.floor(panel/2)*sh,sw,sh,0,0,600,420);}else{ctx.fillStyle='#244534';ctx.fillRect(0,0,600,420);}
 if(mode==='flappy'){for(const o of obstacles){ctx.save();ctx.translate(o.x+26,o.gap-80);ctx.scale(1,-1);sprite(1,0,(o.gap-80)/2,76,o.gap-80);ctx.restore();sprite(1,o.x+26,(420+o.gap+80)/2,76,420-o.gap-80);}sprite(0,160,lemonY,66,66,Math.max(-.45,Math.min(.7,velocity/500)));}
 else if(mode==='cookies'){for(const f of falling)sprite(f.meteor?3:2,f.x,f.y,60,60,f.y/160);sprite(4,basketX,383,128,62);}
 else if(mode==='pop'){for(const f of falling){const x=f.x+Math.sin(f.age*3+f.seed)*9;if(f.sour){ctx.save();ctx.filter='hue-rotate(220deg)';sprite(0,x,f.y,86,86,-.15);ctx.restore();pill(x-28,f.y+25,56,19,'#512664');ctx.fillStyle='white';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.fillText('SOUR',x,f.y+39);}else sprite(0,x,f.y,86,86,-.15);}}
 else{const drinks=['Classic lemon','Pink lemonade','Mint lemonade'];pill(170,58,260,187,'#fffcf2ee');ctx.textAlign='center';ctx.fillStyle='#32543b';ctx.font='bold 17px sans-serif';ctx.fillText('CUSTOMER ORDER',300,88);sprite(5+order,300,147,98,98);ctx.font='bold 20px sans-serif';ctx.fillText(drinks[order],300,210);const remaining=Math.max(0,1-(elapsed-orderTime)/Math.max(2.6,5-runScore*.07));pill(190,225,220*remaining,8,'#85b54b');for(let i=0;i<3;i++){pill(35+i*185,270,160,132,'#fffcf2ef');sprite(5+i,115+i*185,319,86,86);ctx.fillStyle='#32543b';ctx.font='bold 13px sans-serif';ctx.fillText(`${i+1} · ${drinks[i]}`,115+i*185,384);}}
 if(running){pill(14,12,mode==='flappy'?150:230,32,'#173327cc');ctx.fillStyle='#fffbd5';ctx.textAlign='left';ctx.font='bold 16px sans-serif';ctx.fillText(mode==='flappy'?`${runScore} squeezers`:`${Math.max(0,Math.ceil(30-elapsed))}s · ${runScore} scored${mode==='pop'||mode==='rush'?' · '+'♥'.repeat(hearts):''}`,26,34);if(feedbackUntil>elapsed){pill(85,246,430,26,'#173327e8');ctx.textAlign='center';ctx.font='bold 14px sans-serif';ctx.fillStyle='#fffcdb';ctx.fillText(feedback,300,265);}}
 else{ctx.fillStyle='#102a2b80';ctx.fillRect(0,0,600,420);pill(110,106,380,207,'#123729e6');sprite(mode==='cookies'?2:0,300,161,78,78);ctx.fillStyle='#fff8b7';ctx.textAlign='center';ctx.font='bold 29px sans-serif';ctx.fillText(ARCADE_GAMES[mode].title,300,236);ctx.font='16px sans-serif';ctx.fillStyle='#faffee';ctx.fillText('Press Start game below to play',300,274);}
}
function frame(now){if(!running)return;if(window.cloudPaused){endArcade('Game paused.');return;}if(document.hidden){prevTime=now;raf=requestAnimationFrame(frame);return;}const dt=Math.min(.04,Math.max(0,(now-prevTime)/1000));prevTime=now;stepArcade(dt);if(!running)return;drawArcade();raf=requestAnimationFrame(frame);}
function point(event){const r=canvas.getBoundingClientRect();return{x:(event.clientX-r.left)/r.width*600,y:(event.clientY-r.top)/r.height*420};}
function steer(event){basketX=Math.max(48,Math.min(552,point(event).x));}
canvas.addEventListener('pointerdown',e=>{if(!running||window.cloudPaused)return;e.preventDefault();canvas.focus();canvas.setPointerCapture(e.pointerId);if(mode==='flappy')velocity=-265;else if(mode==='cookies')steer(e);else if(mode==='pop'){const p=point(e);const f=[...falling].reverse().find(f=>!f.done&&Math.hypot(p.x-f.x-Math.sin(f.age*3+f.seed)*9,p.y-f.y)<36);if(f){f.done=true;if(f.sour)mistake('Too sour! Find the golden lemons.');else{lemonsPopped++;runScore++;streak++;earnArcade(3000*Math.min(5,1+Math.floor(streak/4)));}}else streak=0;}else{const p=point(e);if(p.y>=270&&p.y<=402)for(let i=0;i<3;i++)if(p.x>=35+i*185&&p.x<=195+i*185)serveDrink(i);}});
canvas.addEventListener('pointermove',e=>{if(running&&!window.cloudPaused&&mode==='cookies'&&(e.buttons||e.pointerType==='touch'))steer(e);});
document.addEventListener('keydown',e=>{if(!$('arcade-dialog').open||!running||window.cloudPaused)return;if(['Space','ArrowUp','ArrowLeft','ArrowRight','Digit1','Digit2','Digit3'].includes(e.code))e.preventDefault();if(e.repeat)return;if(mode==='flappy'&&['Space','ArrowUp'].includes(e.code))velocity=-265;if(mode==='rush'&&/^Digit[123]$/.test(e.code))serveDrink(Number(e.code.slice(-1))-1);if(e.code==='ArrowLeft')leftHeld=true;if(e.code==='ArrowRight')rightHeld=true;});document.addEventListener('keyup',e=>{if(e.code==='ArrowLeft')leftHeld=false;if(e.code==='ArrowRight')rightHeld=false;});window.addEventListener('blur',()=>{leftHeld=rightHeld=false;});
